float hashCell(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float gray(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
vec3 toDisplay(vec3 c) { return mix(c * 12.92, 1.055 * pow(max(c, vec3(0.0)), vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c)); }
vec3 toLinear(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c)); }
float tone(vec3 c) { return clamp((toDisplay(vec3(gray(c))).r - 0.5) * uParam_contrast + 0.48, 0.0, 1.0); }
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / max(iResolution.xy, vec2(1.0));
  vec4 original = vrchSampleSource0(uv);
  float pulse = smoothstep(0.22, 0.72, uParam_cut);
  // The phrase only advances with accumulated cuts; silence cannot invent beats.
  float phrase = vrchPhase_cut() * 4.0;
  float mode = mod(floor(phrase), 4.0);
  float seed = floor(phrase * 0.25);
  float negativeMode = 1.0 - step(0.5, mode);
  float colorMode = step(0.5, mode) * (1.0 - step(1.5, mode));
  float scanMode = step(1.5, mode) * (1.0 - step(2.5, mode));
  float tearMode = step(2.5, mode);
  float row = floor(uv.y * 18.0);
  float selected = step(0.74, hashCell(vec2(row, seed + 9.0)));
  float direction = hashCell(vec2(row + 7.0, seed)) * 2.0 - 1.0;
  float displacement = selected * direction * uParam_tear * (0.24 + 0.76 * pulse);
  vec2 q = clamp(uv + vec2(displacement, 0.0), vec2(0.001), vec2(0.999));
  float mono = tone(vrchSampleSource0(q).rgb);
  vec3 c = vec3(mono);
  // Four large unequal color panels preserve the underlying photograph.
  float panel = step(0.63, uv.x) + 2.0 * step(0.29, uv.y);
  float panelEdge = max(1.0 - smoothstep(0.0, 0.008, abs(uv.x - 0.63)), 1.0 - smoothstep(0.0, 0.006, abs(uv.y - 0.29)));
  vec3 ink = panel < 0.5 ? vec3(0.03, 0.82, 0.92) : panel < 1.5 ? vec3(0.82, 0.03, 0.55) : panel < 2.5 ? vec3(0.40, 0.92, 0.03) : vec3(0.78, 0.02, 0.86);
  float blockStrength = smoothstep(0.18, 0.78, uParam_color) * 0.42;
  vec3 blocked = mix(vec3(mono), vec3(1.0 - mono), ink);
  c = mix(c, ink * (0.10 + mono * 0.90), blockStrength);
  float cutGate = smoothstep(0.30, 0.44, pulse);
  c = mix(c, blocked, cutGate * colorMode);
  c = mix(c, ink * (0.25 + mono * 0.65), panelEdge * uParam_color * 0.28);
  // Crisp exposure changes avoid a lingering, detail-erasing grey crossfade.
  float expose = cutGate * negativeMode;
  float negative = 1.0 - mono;
  c = mix(c, vec3(negative) * vec3(0.93, 0.97, 1.0), expose);
  float aspect = iResolution.y / max(iResolution.x, 1.0);
  vec2 split = vec2(uParam_split * aspect * (0.24 + selected * 0.76 + pulse * 0.8), 0.0);
  float r = tone(vrchSampleSource0(clamp(q + split, vec2(0.001), vec2(0.999))).rgb);
  float b = tone(vrchSampleSource0(clamp(q - split, vec2(0.001), vec2(0.999))).rgb);
  vec3 separated = vec3(mix(r, 1.0 - r, expose), mix(mono, negative, expose), mix(b, 1.0 - b, expose));
  float edges = clamp((abs(r - mono) + abs(b - mono)) * 3.0, 0.0, 1.0);
  c = mix(c, separated, clamp(selected * 0.22 + edges * 0.72, 0.0, 0.85));
  // A cyan displaced exposure crosses a bounded region of the source.
  float scanWindow = smoothstep(0.14, 0.24, uv.x) * (1.0 - smoothstep(0.76, 0.84, uv.x));
  float ghost = 1.0 - tone(vrchSampleSource0(clamp(q + vec2(0.035 * aspect, 0.0), vec2(0.001), vec2(0.999))).rgb);
  float lines = 0.86 + 0.14 * sin(uv.y * min(iResolution.y, 720.0) * 2.0944);
  c = mix(c, vec3(0.28, 0.88, 0.94) * pow(ghost, 1.5) * lines, pulse * scanMode * scanWindow * 0.84);
  float dropout = selected * pulse * tearMode;
  vec3 digital = mix(c * 0.28, vec3(0.12, 0.85, 0.86) * (0.3 + mono * 0.7), step(0.88, hashCell(vec2(row + 21.0, floor(uv.x * 35.0)))));
  c = mix(c, digital, dropout * 0.85);
  float grain = hashCell(floor(fragCoord * 0.65)) - 0.5;
  c = c * (1.0 - uParam_texture * (0.025 + 0.025 * sin(uv.y * min(iResolution.y, 720.0) * 2.0944))) + grain * uParam_texture * 0.022;
  fragColor = vec4(mix(original.rgb, toLinear(clamp(c, 0.0, 1.0)), uParam_amount), original.a);
}
